local InstructionType = 
{
    OpenRoom = 1, 
    CloseRoom = 2, 
    OpenDoor = 3, 
    CloseDoor = 4
}


-- ========================================================


function RoomActivator:__init()
    self.controller = nil

    self.isRoomManageActive = true  -- 本实例是否 可以控制 room激活禁用 的开启关闭
    self.isDoorMotionActive = false -- 本实例是否 可以控制 自动感应门的开启关闭, 被外部设置
    self.isRoleCloseEnough = false  -- 只有当 role 足够接近时, 本功能才会启用 
    self.isInit = false

    -- role 当前是否在 inn半径 ? 是否在 out半径 ?
    self.innState = ElectrifiedState( OnOff.Off, IsFirstFrame.No )
    self.outState = ElectrifiedState( OnOff.Off, IsFirstFrame.No )
    
    -- 上一帧是否进入 inn半径, out半径 ?
    self.isLastFrameEnterInnRadius = false 
    self.isLastFrameEnterOutRadius = false 

    self.doorState = DoorState.DoNothing

    -- 存储: 开门,关门,激活房间,隐藏房间 系列指令
    -- first 就是当前正在处理的指令, 只有等它处理完后, 才会被删除
    self.instructionQueue = Queue.New( 100 ) 

end



function RoomActivator:__delete()
end




function RoomActivator:Awake()

    self.transform = self.controller.gameObject.transform
    assert( (self.transform.localScale - Vector3.one).sqrMagnitude < 0.01, "RoomActivator localScale 必须为 (1,1,1)" )
    
    ---
    assert( self.doorPivotDown and self.doorPivotUp )

    


    local doorLen = (self.doorPivotDown.position - self.doorPivotUp.position).magnitude
    assert( doorLen > 0.01 ) -- door segment 不能太短

    -- params ---:
    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )
    self.doorFrontLen = LuaParametersReader.Read( self.params, "doorFrontLen", LuaParametersReader.Type.Float ) -- 门前距离
    local doorMotionExtraRadius = LuaParametersReader.Read( self.params, "doorMotionExtraRadius", LuaParametersReader.Type.Float )  -- (内圈) 门开关半径   附加值
    local roomManageExtraRadius = LuaParametersReader.Read( self.params, "roomManageExtraRadius", LuaParametersReader.Type.Float )  -- (外圈) 资源激活半径 附加值
    local verticalThresholdVal     = LuaParametersReader.Read( self.params, "verticalThreshold",     LuaParametersReader.Type.Float )  -- 垂直方向判断距离
    local isInitDoorMotionActive = LuaParametersReader.Read( self.params, "isInitDoorMotionActive", LuaParametersReader.Type.Bool ) -- 是否在一开始就支持自动感应门 
    assert( self.doorFrontLen and doorMotionExtraRadius and roomManageExtraRadius and verticalThresholdVal and type(isInitDoorMotionActive) == "boolean" )

    self.isDoorMotionActive = isInitDoorMotionActive

    self.innRadius = doorLen * 0.5 + doorMotionExtraRadius
    self.outRadius = doorLen * 0.5 + roomManageExtraRadius
    self.outRadius = Mathf.Max( self.innRadius + 0.1, self.outRadius ) -- 确保 外圈一定比内圈大一点

    self.verticalThreshold = Mathf.Max( 0.0,  verticalThresholdVal )

    ---
    self:InitDoor()

    ---
    self:InitOuterCollider()
end


-- 初始化 门
function RoomActivator:InitDoor()

    self.doorCenterPos = (self.doorPivotDown.position + self.doorPivotUp.position) * 0.5
    self.doorDown2Up = (self.doorPivotDown.position - self.doorPivotUp.position) -- 未归一化
    self.doorDown2UpLen = self.doorDown2Up.magnitude
    self.doorLeft2Right = -Vector3.Cross( self.doorDown2Up.normalized, Vector3.up ) -- 未归一化
    ---
    local doorLeft2RightDir = self.doorLeft2Right.normalized
    self.doorPivotLeftPos  = self.doorCenterPos + doorLeft2RightDir * self.doorFrontLen
    self.doorPivotRightPos = self.doorCenterPos - doorLeft2RightDir * self.doorFrontLen
    -- print( "koko Pivot Left = " .. self.doorPivotLeftPos:ToString() )
    -- print( "koko Pivot Right = " .. self.doorPivotRightPos:ToString() )
end



-- 自动计算 outerCollider 的尺寸, 让它适配 outRadius 
-- 只有 roleDelayFollow 进入 outerCollider, 本 RoomActivator 才会开始运算
function RoomActivator:InitOuterCollider()

    self.outerCollider = KTool.GetComponent(self.controller.gameObject, typeof(SphereCollider))
    assert( self.outerCollider )
    self.outerCollider.isTrigger = true

    local segmentDir = self.doorPivotUp.position - self.doorPivotDown.position
    local segmentHalfLen = segmentDir.magnitude * 0.5
    segmentDir = segmentDir.normalized
    
    self.outerCollider.center = self.doorCenterPos - self.transform.position
    self.outerCollider.radius = Mathf.Max( self.doorDown2UpLen * 0.5, self.doorFrontLen ) + self.outRadius + 2.0 -- 要额外宽出一段距离, 但这不是最好的办法...
end




function RoomActivator:Start()

    KTool.SetActive(self.controller.gameObject, true);

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
        behaviourAction.OnTriggerExitAction = function(behaviourAction,other_)
            self:OnTriggerExit(other_)
        end
    end
    -- ==================================:

    assert( self.simpleSlidingDoorBH )
    self.simpleSlidingDoor = DreamSpaceLuaUtils.GetLuaScr(self.simpleSlidingDoorBH.gameObject, "Game.DreamSpace.ElectricalSystem.Appliance.SimpleSlidingDoor" )
    assert( self.simpleSlidingDoor )

    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end



function RoomActivator:DelayInit()

    cs_coroutine.yield_return( RoomActivatorManager.WaitInstance() ) -- 等待实例化
    self.roomActivatorManager = RoomActivatorManager.GetInstance()   -- 拿到唯一实例

    coroutine.yield(Yielders.EndOfFrame)
    ---
    assert( self.roomLeftBH and self.roomRightBH )
    assert( self.roomLeftBH ~= self.roomRightBH )
    self.roomLeft  = DreamSpaceLuaUtils.GetLuaScr(self.roomLeftBH.gameObject,  "Game.DreamSpace.Performance.RoomActivator.Room" )
    self.roomRight = DreamSpaceLuaUtils.GetLuaScr(self.roomRightBH.gameObject, "Game.DreamSpace.Performance.RoomActivator.Room" )

    assert( isNotNull(self.roomLeft) )
    assert( isNotNull(self.roomRight) )

    self.roomActivatorManager:AddRoom( self.roomLeft )
    self.roomActivatorManager:AddRoom( self.roomRight )

    --self.roomActivatorManager:AddRoomActivator( self, self.roomLeftTF, self.roomRightTF )

    -- role 对面的房间, 注意 key 要反着装:
    self.oppositeRoomInstanceIDs = {}
    self.oppositeRoomInstanceIDs[RoomSide.Right] = self.roomLeft.transform:GetInstanceID()
    self.oppositeRoomInstanceIDs[RoomSide.Left] = self.roomRight.transform:GetInstanceID()


    cs_coroutine.yield_return( self.roomActivatorManager:FindRole() )

    coroutine.yield(Yielders.EndOfFrame)
    self.simpleSlidingDoor:SetDoorOpenInitially( false ) -- 初始阶段强制关门

    self.isInit = true
end




function RoomActivator:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.OpenDoorCoroutine )
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.OpenDoorCoroutine = nil
    self.co_0 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


---@param other_ UnityEngine.Collider
function RoomActivator:OnTriggerEnter(other_)
    print( "OnTrigger Enter: " .. self.controller.gameObject.name .. ";  " .. other_.name )
    self.isRoleCloseEnough = true
end


---@param other_ UnityEngine.Collider
function RoomActivator:OnTriggerExit(other_)
    print( "OnTrigger Exit: " .. self.controller.gameObject.name .. ";  " .. other_.name )
    self.isRoleCloseEnough = false
end



function RoomActivator:Update()
    if self.isInit ~= true then 
        return
    end 


    if self.isRoleCloseEnough == true then 
        local roleDistance = self:CalculateDistance()   

        -- out
        if self.isRoomManageActive == true then

            local isEnterOutRadius = roleDistance < self.outRadius -- 本帧 role 是否进入 out半径
            self.outState.isOn         = (isEnterOutRadius == true) and OnOff.On or OnOff.Off
            self.outState.isFirstFrame = (isEnterOutRadius ~= self.isLastFrameEnterOutRadius) and IsFirstFrame.Yes or IsFirstFrame.No
            self.isLastFrameEnterOutRadius = isEnterOutRadius

            if self.outState.isFirstFrame == IsFirstFrame.Yes then 
                self:CalculateRoleInWhithSide()

                --print( "room 指令" )

                if self.outState.isOn == OnOff.On then 
                    -- 检查并 激活对面room:
                    print( "指令 添加: OpenRoom: " .. self.oppositeRoomInstanceIDs[self.roleInWhithSide] )
                    self.instructionQueue:AddLast({
                        type = InstructionType.OpenRoom, 
                        nextType = nil,
                        frameIdx = 0,
                        RoomInstanceID = self.oppositeRoomInstanceIDs[self.roleInWhithSide], 
                    })

                else 
                    -- 检查并 关闭对方room:
                    print( "指令 添加: CloseRoom: " .. self.oppositeRoomInstanceIDs[self.roleInWhithSide] )
                    self.instructionQueue:AddLast({
                        type = InstructionType.CloseRoom, 
                        nextType = nil,
                        frameIdx = 0,
                        RoomInstanceID = self.oppositeRoomInstanceIDs[self.roleInWhithSide], 
                    })

                end
            end 
        end

        -- inn
        if self.isDoorMotionActive == true then 
            local isEnterInnRadius = roleDistance < self.innRadius -- 本帧 role 是否进入 inn半径
            self.innState.isOn         = (isEnterInnRadius == true) and OnOff.On or OnOff.Off
            self.innState.isFirstFrame = (isEnterInnRadius ~= self.isLastFrameEnterInnRadius) and IsFirstFrame.Yes or IsFirstFrame.No
            self.isLastFrameEnterInnRadius = isEnterInnRadius

            if self.innState.isFirstFrame == IsFirstFrame.Yes then 
                -- 需要 开门/关门:

                local lastInstruction = self.instructionQueue:PeekLast()

                local _type = (self.innState.isOn == OnOff.On) and InstructionType.OpenDoor or InstructionType.CloseDoor
                --print( "指令 添加: " .. ((self.innState.isOn == OnOff.On) and "OpenDoor" or "CloseDoor") )

                self.instructionQueue:AddLast({
                    type = _type,
                    nextType = nil,
                    frameIdx = 0,
                })

                if isNotNull(lastInstruction) then 
                    lastInstruction.nextType = _type
                end 
            end 
        end
    end

    -------- 处理指令: ---------
    if self.instructionQueue:Count() > 0 then
        local instruction = self.instructionQueue:PeekFirst()

        local frameIdx = instruction.frameIdx
        instruction.frameIdx = instruction.frameIdx + 1

        if frameIdx == 0 then 
            -- 指令的第一帧:
            self:StartInstruction( instruction )
        else
            -- 指令的后续帧:
            if instruction.type == InstructionType.OpenRoom or instruction.type == InstructionType.CloseRoom then 

                local room = self.roomActivatorManager:GetRoom( instruction.RoomInstanceID )

                if room.isWorking == false then  
                    -- room 激活/隐藏 结束: 
                    self.instructionQueue:RemoveFirst();
                    --- 启动下一个指令:
                    if self.instructionQueue:Count() > 0 then 
                        local next = self.instructionQueue:PeekFirst() 
                        assert( isNotNull(next) )
                        self:StartInstruction( next )
                    end 

                end 
               
            elseif instruction.type == InstructionType.OpenDoor or instruction.type == InstructionType.CloseDoor then 

                if      instruction.nextType == InstructionType.OpenDoor or instruction.nextType == InstructionType.CloseDoor -- 若下一个指令也是门运动, 可直接中断本指令
                    or  self.simpleSlidingDoor:IsDoorMoving() == false 
                then 
                    -- 门的运动结束:
                    self.instructionQueue:RemoveFirst();
                    --- 启动下一个指令:
                    if self.instructionQueue:Count() > 0 then 
                        local next = self.instructionQueue:PeekFirst() 
                        assert( isNotNull(next) )
                        self:StartInstruction( next )
                    end 
                end 
            else 
                assert( false, "instruction type 异常: " .. checkString(instruction.type) )
            end
        end
    end 
    

end



-- =========================================== Self ================================================ --


function RoomActivator:StartInstruction( instruction_ )
    if instruction_.type == InstructionType.OpenRoom then 
        self.roomActivatorManager:SetRoom( instruction_.RoomInstanceID, true ) -- 要求 激活 对面房间
    elseif instruction_.type == InstructionType.CloseRoom then
        self.roomActivatorManager:SetRoom( instruction_.RoomInstanceID, false ) -- 要求 隐藏 对面房间
    elseif instruction_.type == InstructionType.OpenDoor then
        DreamSpaceLuaUtils.StopCoroutine( self.OpenDoorCoroutine )
        self.OpenDoorCoroutine = cs_coroutine.start(function() self.simpleSlidingDoor:Open( true ) end) -- 要求开门
    elseif instruction_.type == InstructionType.CloseDoor then
        DreamSpaceLuaUtils.StopCoroutine( self.OpenDoorCoroutine )
        self.OpenDoorCoroutine = cs_coroutine.start(function() self.simpleSlidingDoor:Open( false ) end) -- 要求关门
    else 
        assert( false, "instruction type 异常: " .. checkString(instruction_.type) )
    end
end




-- 计算 roleDelayFollow 距离 door 线段的 距离
function RoomActivator:CalculateDistance()

    local rolePos = self.roomActivatorManager.roleDelayFollow.transform.position
    ---
    if Mathf.Abs(rolePos.y-self.doorCenterPos.y) > self.verticalThreshold then 
        return 999.0
    end 

    -- !!! 调用 c# 版 ElectricWireUtils.CheckCollide_Point_With_Segment() 会导致 GC, 大概是存在 out 参数的原因; 目前改用 lua 版
    -- distance2:   最短路径的 距离平方
    -- local_t:     最短路径 在 线段 上的 t值
    -- TouchPos:    计算得到的最短线段 在 线段 上的点
    -- local distance2, _local_t, _touchPos = ElectricWireUtils.CheckCollide_Point_With_Segment( rolePos, self.doorPivotLeftPos, self.doorPivotRightPos )
    local distance2 = RoomActivator.CheckCollide_Point_With_Segment( rolePos, self.doorPivotLeftPos, self.doorPivotRightPos )

    local distance = Mathf.Sqrt( distance2 ) - self.roomActivatorManager.roleDelayFollow.colliderRadius
    --print( "distance = " .. distance )
    return distance
end



-- 替代 c# 版 ElectricWireUtils.CheckCollide_Point_With_Segment(),  调用无GC:
--
function RoomActivator.CheckCollide_Point_With_Segment( PointPos, segment_p1, segment_p2 )

    local a2b = segment_p2 - segment_p1
    local a2p = PointPos - segment_p1
    local b2p = PointPos - segment_p2
    local project = Vector3.Dot( a2b, a2p ) -- 投影
    local a2bLen2 = Vector3.Dot( a2b, a2b ) -- 长度平方
    local a2pLen2 = Vector3.Dot( a2p, a2p ) -- 长度平方

    -- 说明 点 离 p1 最近:
    if project < 0.0 then
        return a2pLen2
    end 

    -- 说明 点 离 p2 最近:
    if project > a2bLen2  then
        return Vector3.Dot( b2p, b2p )
    end

    -- 说明 最短路径点 位于 线段体内:
    local projectLen2 = project * project / a2bLen2 -- 投影向量 长度的平方
    return a2pLen2 - projectLen2 -- 勾股定理
end




function RoomActivator:CalculateRoleInWhithSide()
    local a = self.doorPivotUp.position - self.doorPivotDown.position 
    local b = self.roomActivatorManager.roleDelayFollow.transform.position - self.doorPivotDown.position
    local dot = Vector3.Dot( Vector3.Cross( a,b ), Vector3.up)
    --print( "dot = " .. dot )
    self.roleInWhithSide = (dot<0.0) and RoomSide.Left or RoomSide.Right
end



return RoomActivator
